B.hT=new A.lC(1,"shiftModifier")
B.hU=new A.lC(2,"altModifier")
B.hV=new A.lC(3,"metaModifier")
B.rl=new A.lC(4,"capsLockModifier")
B.rm=new A.lC(5,"numLockModifier")
B.rn=new A.lC(6,"scrollLockModifier")
B.ro=new A.lC(7,"functionModifier")
B.JX=new A.lC(8,"symbolModifier")
B.DY=s([B.hS,B.hT,B.hU,B.hV,B.rl,B.rm,B.rn,B.ro,B.JX],A.a9("y<lC>"))
B.DZ=s(["E","P","M","A","M","Hun","Hul","Ago","Set","Okt","Nob","Dis"],t.s)
B.axQ=s(["Kabla ya Kristo","Baada ya Kristo"],t.s)
B.axS=s(["\u0db4\u0dd9.\u0dc0.","\u0db4.\u0dc0."],t.s)
B.E_=s(["\u0d89","\u0dc3","\u0d85","\u0db6","\u0db6\u0dca\u200d\u0dbb","\u0dc3\u0dd2","\u0dc3\u0dd9"],t.s)
B.axT=s(["eram\u0131zdan \u0259vv\u0259l","yeni era"],t.s)
B.dB=s(["1st quarter","2nd quarter","3rd quarter","4th quarter"],t.s)
B.axU=s(["\u0e01\u0e48\u0e2d\u0e19 \u0e04.\u0e28.","\u0e04.\u0e28."],t.s)
